import re


def parse_version(version_str: str) -> tuple[int, ...]:
    """SemVer formatına göre versiyonu parse eder.

    Örnekler: 'v1.2.3', '-alpha.1', '+build.5', 'v1.0.0-beta.2'
    Başlangıç sıfıra izin verilmez (0 hariç).
    """
    # v ile başlar veya ön sürüm/derleme bilgisi varsa
    if version_str.startswith('v'):
        version_str = version_str[1:]

    # SemVer formatına göre parse et: MAJOR.MINOR.PATCH
    pattern = r'^(\d+)\.(\d+)\.(\d+)$'
    match = re.match(pattern, version_str)
    if not match:
        raise ValueError(f"Geçersiz versiyon metni: {version_str}")

    major, minor, patch = map(int, match.groups())
    return (major, minor, patch)


def compare(a: str, b: str) -> int:
    """a < b ise -1, eşit öncelikteyse 0, a > b ise 1.

    SemVer kurallarına göre karşılaştırma yapar.
    Derleme bilgisi (build) önceliği etkilemez.
    Başta isteğe bağlı tek bir 'v' olabilir.
    """
    try:
        parse_version(a)
        parse_version(b)
    except ValueError:
        raise ValueError("Geçersiz versiyon metni")

    a_parts = parse_version(a)
    b_parts = parse_version(b)

    # Her iki tarafı eşit öncelikte karşılaştırmak için önce 'v' kontrolü
    if len(a_parts) != len(b_parts):
        return 1 - (len(a_parts) - len(b_parts))

    for i in range(len(a_parts)):
        a_val = a_parts[i]
        b_val = b_parts[i]

        # Eğer bir taraf sıfırsa, diğerinin sıfır olup olmadığını kontrol et
        if a_val == 0 and b_val != 0:
            return -1
        elif b_val == 0 and a_val != 0:
            return 1

        if a_val < b_val:
            return -1
        elif a_val > b_val:
            return 1

    # Eşit öncelikte, aynı sürüm metnini karşılaştırmak için 'v' kontrolü
    if len(a_parts) == 3 and len(b_parts) == 3:
        if a != b:
            return -1 if a < b else (1 if a > b else 0)

    # Her iki taraf da aynı sürüm metnini ise eşit öncelik
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    """Önceliğe göre artan sıralı yeni liste. Eşit öncelikli sürümler girdideki sıralarını korusun."""
    sorted_list = []

    for version in versions:
        try:
            parse_version(version)
            # compare fonksiyonu ile sırala
            is_sorted = True
            for i, other in enumerate(sorted_list):
                cmp = compare(version, other)
                if cmp < 0:
                    sorted_list.insert(i, version)
                    break
                elif cmp > 0:
                    sorted_list.insert(i + 1, version)
                    is_sorted = False
                    break
            else:
                # Eşit öncelikli sürümler için girdideki sıralarını koru
                sorted_list.append(version)
        except ValueError:
            raise ValueError("Geçersiz versiyon metni")

    return sorted_list

